using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[Authorize(Roles="Admin"),ApiController,Route("api/admin")]public class AdminController(IUnitOfWork uow,IGenericRepository<Report> reports):ControllerBase{[HttpGet("users")]public async Task<IActionResult>Users(CancellationToken ct)=>Ok(ApiResponse<List<User>>.Ok(await uow.Users.ListAsync(null,ct)));[HttpGet("reports")]public async Task<IActionResult>Reports(CancellationToken ct)=>Ok(ApiResponse<List<Report>>.Ok(await reports.ListAsync(null,ct)));[HttpPut("ads/{id:int}/status")]public async Task<IActionResult>AdStatus(int id,[FromBody]string status,CancellationToken ct){var a=await uow.Ads.GetByIdAsync(id,ct)??throw new KeyNotFoundException();a.Status=status;uow.Ads.Update(a);await uow.SaveChangesAsync(ct);return Ok(ApiResponse<Ad>.Ok(a));}}
